const data = $input.first().json;
const date = data.date || new Date().toISOString().slice(0, 10);
const total = data.total || 0;
const rows = data.rows || [];

let htmlRows = rows.map(r => `<tr><td style="padding:6px;border:1px solid #ddd;">${r.location}</td><td style="padding:6px;border:1px solid #ddd;">${r.specialty}</td><td style="padding:6px;border:1px solid #ddd;">${r.status}</td><td style="padding:6px;border:1px solid #ddd;text-align:right;"><b>${r.total}</b></td></tr>`).join('');

const body = `<h3>Resumen Operativo Diario - MediHealth Plus (${date})</h3><p>Total de citas del día: <b>${total}</b></p><table style="border-collapse:collapse;width:100%;font-family:sans-serif;"><thead><tr style="background:#f2f2f2;"><th style="padding:6px;border:1px solid #ddd;">Sede</th><th style="padding:6px;border:1px solid #ddd;">Especialidad</th><th style="padding:6px;border:1px solid #ddd;">Estado</th><th style="padding:6px;border:1px solid #ddd;">Cantidad</th></tr></thead><tbody>${htmlRows || '<tr><td colspan="4" style="padding:6px;text-align:center;">Sin actividad registrada</td></tr>'}</tbody></table>`;

return [{ json: { date, total, htmlBody: body } }];
